import{z as B,x as s,o as E,c as o,q as t,j as r,D as e,d as p,s as n,S as m}from"./chunks/framework.C8m1ZpeB.js";const T=JSON.parse('{"title":"接受率的理论与测量","description":"","frontmatter":{"title":"接受率的理论与测量","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/spec-acceptance-theory.md","filePath":"llm/spec-acceptance-theory.md","lastUpdated":1791063341000}'),A={name:"llm/spec-acceptance-theory.md"};function h(i,a,c,d,C,D){const l=s("Mermaid");return E(),o("div",null,[a[2]||(a[2]=t('<h1 id="接受率的理论与测量" tabindex="-1">接受率的理论与测量 <a class="header-anchor" href="#接受率的理论与测量" aria-label="Permalink to &quot;接受率的理论与测量&quot;">​</a></h1><div class="epigraph"><p>接受率不是草稿的属性，是两个分布的重叠：说「我的草稿接受率 0.7」，等于什么都没说，除非连着温度、任务和位置。</p><footer>—— 据 Leviathan et al., ICML 2023 与 Chen et al., 2023 的似然比口径整理</footer></div><p><a href="/llm/spec-longoutput">上一课</a>把长输出里接受率的漂移摊开，理论与方法单元从 \\(\\alpha\\) 本身开始。<a href="/llm/spec-acceptance-rate">接受率与加速比</a>给过几何期望，<a href="/llm/acceptance-length-sched">接受长度调度</a>把 \\(\\tau\\) 当资源调度假定过 i.i.d.。本课把地基钉牢：\\(\\alpha\\) 的严格定义、它与分布距离的关系、以及测量里最容易出错的三处偏差。前面各课拿 \\(\\alpha\\) 当已知量用，本课回答它从哪来、怎么量才不算错。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>工程报告里的「接受率」至少混着三个不同的量：逐位置接受概率、每轮实现的接受长度、贪心下的逐步一致率。三者数值不同、用途不同，混用会让 \\(\\gamma\\) 调优与草稿选型都在错误的数上做决策。更隐蔽的是测量偏差：接受事件只发生在草稿实际走到的状态上，而草稿走哪条路由 \\(q\\) 自己决定——拿这些样本平均，得到的是 \\(q\\) 分布下的量；决策却要 \\(p\\) 分布（真实前缀分布）下的量。采样参数一动，同一对模型的所有数字全变。没有严格定义，前面各课的桶统计、在线路由、位置分桶都缺一个可比较的锚。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><strong>定义</strong>。逐位置接受概率是重叠质量：</p> \\[\\alpha \\;=\\; \\sum_{x}\\min\\bigl(p(x),\\,q(x)\\bigr)\\;=\\;1-\\mathrm{TV}(p,q), \\]<p>其中 \\(\\mathrm{TV}(p,q)=\\tfrac{1}{2}\\sum_x|p(x)-q(x)|\\) 是全变差距离。\\(\\alpha=1\\) 当且仅当两分布相同；\\(\\alpha\\) 随分布分离单调降到 0。i.i.d. 假定下每轮期望前进 \\(\\tau=(1-\\alpha^{\\gamma+1})/(1-\\alpha)\\)，已在<a href="/llm/acceptance-length-sched">接受长度调度</a>推过，不重推。<strong>散度上界</strong>。\\(\\mathrm{TV}\\) 难直接测，Pinsker 不等式把它接到 KL：</p> \\[\\mathrm{TV}(p,q)\\;\\leq\\;\\sqrt{\\mathrm{KL}(q\\,\\|\\,p)/2}, \\]<p>而 \\(\\mathrm{KL}(q\\|p)\\) 可以离线估计：让草稿生成文本，逐 token 记下 \\(\\log q-\\log p\\) 的均值。这给了草稿选型一个便宜的前置指标：不用跑完整投机闭环就能给候选排座次。<strong>测量协议</strong>。逐位置 \\(\\hat\\alpha\\) 用「草稿访问到的状态」上 \\(\\min(1,p/q)\\) 的均值估计——这是 \\(q\\) 下的无偏量，报告时要标明；真正用于收益预期的是它在真实前缀分布上的值，两者随草稿质量差距增大而分离。温度、任务、输出位置必须分桶；贪心场景的「一致率」单独一栏，不与采样 \\(\\alpha\\) 并列。</p><p><span class="marginnote">术语翻译：「全变差距离 TV」就是把两份概率表逐项相减、取绝对值、加起来再除以二。\\(\\min(p,q)\\) 则可以想成两堆沙叠在一起时较薄的那一层——形状越接近，能直接对上的沙越多，\\(\\alpha\\) 就是这层「对得上的沙」占总量的比例。</span></p>',12)),(E(),r(m,null,{default:e(()=>[n(l,{id:"mermaid-30",class:"mermaid",graph:"flowchart%20TD%0A%20%20DEF%5B%22%E5%AE%9A%E4%B9%89%EF%BC%9A%CE%B1%20%3D%201%20%E2%88%92%20TV(p%2Cq)%22%5D%20--%3E%20BND%5B%22Pinsker%EF%BC%9ATV%20%E2%89%A4%20%E2%88%9A(KL%2F2)%22%5D%0A%20%20BND%20--%3E%20OFF%5B%22%E7%A6%BB%E7%BA%BF%EF%BC%9A%E8%8D%89%E7%A8%BF%E6%96%87%E6%9C%AC%E4%B8%8A%E4%BC%B0%20KL(q%E2%80%96p)%20%E6%8E%92%E5%BA%A7%E6%AC%A1%22%5D%0A%20%20DEF%20--%3E%20EST%5B%22%E5%9C%A8%E7%BA%BF%EF%BC%9Aq%20%E8%AE%BF%E9%97%AE%E6%80%81%E4%B8%8A%E4%BC%B0%20min(1%2C%20p%2Fq)%22%5D%0A%20%20EST%20--%3E%20BUC%5B%22%E6%8C%89%E6%B8%A9%E5%BA%A6%20%2F%20%E4%BB%BB%E5%8A%A1%20%2F%20%E4%BD%8D%E7%BD%AE%E5%88%86%E6%A1%B6%22%5D%0A%20%20OFF%20--%3E%20DEC%5B%22%E8%8D%89%E7%A8%BF%E9%80%89%E5%9E%8B%E4%B8%8E%20%CE%B3%20%E9%A2%84%E8%B0%83%22%5D%0A%20%20BUC%20--%3E%20DEC%0A%20%20DEC%20--%3E%20MON%5B%22%E7%9C%8B%E6%9D%BF%EF%BC%9A%E6%A1%B6%E7%BA%A7%20%CE%B1%20%2B%20%E5%AE%9E%E7%8E%B0%E7%9A%84%20%CF%84%20%E5%88%86%E5%B8%83%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>接受规则与 \\(\\mathrm{TV}\\) 的关系比「恰好相等」更深：拒绝点的修正分布 \\(\\mathrm{norm}(\\max(0,p-q))\\) 的总质量恰是 \\(\\tfrac12\\sum_x|p-q|=\\mathrm{TV}(p,q)\\)——被拒绝的概率质量与两分布的分离度是同一个数。所以「草稿差多少」和「平均拒多少次」不是两件事的巧合，而是同一枚硬币。Pinsker 那一侧的机制是 KL 对尾部敏感、\\(\\mathrm{TV}\\) 对单点敏感：草稿把高概率峰放对、尾巴乱放，\\(\\mathrm{TV}\\) 小、\\(\\alpha\\) 高；草稿把峰放错一个 token，\\(\\mathrm{TV}\\) 直接吃掉那份质量。这解释了<a href="/llm/spec-self-draft-medusa">自投机与多 token 头</a>到<a href="/llm/spec-eagle-family">特征级草稿</a>的谱系为什么有效——它们都在把 \\(q\\) 的峰往 \\(p\\) 的峰上搬，而不是把整条分布磨平。</p><p><span class="marginnote">Pinsker 用自然对数：\\(\\mathrm{KL}=0.1\\) nats 给 \\(\\mathrm{TV}\\leq\\sqrt{0.05}\\approx0.22\\)，即 \\(\\alpha\\geq0.78\\)。注意方向：界给的是下限，实际 \\(\\alpha\\) 可以高得多——界用来快速淘汰烂草稿，不用来精确预测收益。</span></p><p><span class="marginnote">数字实例：设目标模型给「猫」0.6 的概率，草稿却把峰全压给了「狗」。仅这一个 token，TV 就被吃掉 \\(|0.6-0|/2=0.3\\)，\\(\\alpha\\) 从 1 掉到不超过 0.7。这就是「峰放错一个位置」比「整条尾巴乱放」代价大得多的算术来源。</span></p>',4)),(E(),r(m,null,{default:e(()=>[n(l,{id:"mermaid-43",class:"mermaid",graph:"flowchart%20TD%0A%20%20S%5B%22%E8%8D%89%E7%A8%BF%E6%A8%A1%E5%9E%8B%E4%BB%8E%20q%20%E6%8A%BD%E5%87%BA%E5%80%99%E9%80%89%20token%20x%22%5D%20--%3E%20U%5B%22%E6%8A%9B%E4%B8%80%E4%B8%AA%E5%9D%87%E5%8C%80%E9%9A%8F%E6%9C%BA%E6%95%B0%20u%22%5D%0A%20%20U%20--%3E%20C%7B%22u%20%E5%B0%8F%E4%BA%8E%20p(x)%2Fq(x)%20%3F%22%7D%0A%20%20C%20--%3E%7C%22%E6%98%AF%22%7C%20A%5B%22%E6%8E%A5%E5%8F%97%20x%2C%20%E5%89%8D%E8%BF%9B%E4%B8%80%E6%AD%A5%22%5D%0A%20%20C%20--%3E%7C%22%E5%90%A6%22%7C%20R%5B%22%E4%BB%8E%E4%BF%AE%E6%AD%A3%E5%88%86%E5%B8%83%20norm(max(0%2C%20p%E2%88%92q))%20%E9%87%8D%E6%8A%BD%E4%B8%80%E4%B8%AA%20token%22%5D%0A%20%20R%20--%3E%20N%5B%22%E6%8F%90%E4%BA%A4%E7%BA%A0%E6%AD%A3%20token%2C%20%E6%9C%AC%E8%BD%AE%E7%BB%93%E6%9D%9F%22%5D%0A%20%20A%20--%3E%20K%5B%22%E7%BB%A7%E7%BB%AD%E8%B5%B7%E8%8D%89%E4%B8%8B%E4%B8%80%E8%BD%AE%E8%8D%89%E7%A8%BF%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[p(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>i.i.d. 是工作假设不是事实：接受事件有后效（走偏后更易继续拒），有效 \\(\\tau\\) 低于公式预测，长输出上尤其明显——<a href="/llm/spec-longoutput">长输出场景的投机</a>的位置分桶就是在补这个洞。\\(\\mathrm{TV}\\) 定义的是采样接受；typical acceptance 一类放宽变体有自己的「接受率」，与 \\(\\alpha\\) 不可比。贪心一致率、采样 \\(\\alpha\\)、逐轮 \\(\\tau\\) 三个量各进各的栏。最后，\\(\\alpha\\) 高不等于该开投机：收益还要除以成本比，<a href="/llm/spec-online-draft-selection">在线草稿模型选择</a>的桶账才是决策位，本课交付的只是账里那个最容易被量错的分子。</p><p><span class="marginnote">常见误区：初学者容易拿不同温度下的 \\(\\alpha\\) 直接比大小，得出「这草稿变好了/变差了」的结论。实际上温度一改，\\(p\\) 和 \\(q\\) 两份分布都被重整化，重叠度整体平移——要比，就锁定同一组采样参数，只让草稿本身变。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>逐位置接受概率有严格定义：\\(\\alpha=1-\\mathrm{TV}(p,q)\\)，是两个分布的重叠质量，不是草稿的单独属性。</li><li>修正分布的正部质量恰等于 \\(\\mathrm{TV}\\)：拒绝多少与分布分离多少是同一个量。</li><li>Pinsker 把 \\(\\mathrm{TV}\\) 接到 \\(\\mathrm{KL}(q\\|p)\\)：离线估 KL 即可给草稿候选排座次，不必跑完整闭环。</li><li>测量三纪律：标明采样分布（\\(q\\) 访问态 vs 真实前缀）、温度任务位置分桶、贪心一致率单独记。</li><li>i.i.d. 公式是基线不是保证，后效让有效 \\(\\tau\\) 低于预测；\\(\\alpha\\) 高仍要到桶账上过成本关。</li><li>出处：Leviathan et al., ICML 2023；Chen et al., 2023；\\(\\mathrm{TV}\\) 与 Pinsker 不等式见 Cover &amp; Thomas, <em>Elements of Information Theory</em>。</li></ul>',5))])}const _=B(A,[["render",h]]);export{T as __pageData,_ as default};
